{"action":"write","path":"duration.py","content":"import re

_SECONDS_PER_UNIT = {
    "d": 24 * 60 * 60,
    "h": 60 * 60,
    "m": 60,
    "s": 1,
}

_DURATION_RE = re.compile(
    r"\s*(?:([0-9]+)d)?(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?\s*"
)


def parse_duration(s):
    """Parse a duration string such as '1h30m' into an integer number of seconds.

    Units must appear at most once and in the order d, h, m, s. Any invalid
    input, including an empty string or a bare number, raises ValueError.
    """
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _DURATION_RE.fullmatch(s)
    if match is None or all(value is None for value in match.groups()):
        raise ValueError(f"invalid duration: {s!r}")

    total = 0
    for amount, unit in zip(match.groups(), ("d", "h", "m", "s")):
        if amount is not None:
            total += int(amount) * _SECONDS_PER_UNIT[unit]
    return total
